begin;
set local search_path=public,extensions;
select plan(72);
select is((select provolatile::text from pg_proc where oid='private.checklist_authoring_items_are_valid(jsonb)'::regprocedure),'s','validator volatility conservatively matches storage-size dependency');
select ok((select pg_get_userbyid(proowner)='postgres' and prosecdef and proconfig=array['search_path=""','row_security=off'] from pg_proc where oid='private.checklist_authoring_items_are_valid(jsonb)'::regprocedure),'validator owner, definer and fixed execution configuration preserved');
select ok(not has_function_privilege('anon','private.checklist_authoring_items_are_valid(jsonb)','execute') and not has_function_privilege('authenticated','private.checklist_authoring_items_are_valid(jsonb)','execute'),'browser roles cannot call private validator');
create temporary table shape_cases(id text,input jsonb,expected boolean) on commit drop;
select is(private.checklist_authoring_items_are_valid(input),expected,'authoring shape: '||id) from shape_cases order by id;
create temporary table plain_values(id int,validation jsonb,items jsonb) on commit drop;
alter table plain_values alter column validation set storage external;
alter table plain_values alter column items set storage external;
create temporary table compressed_values(like plain_values) on commit drop;
alter table compressed_values alter column validation set storage extended;
alter table compressed_values alter column validation set compression pglz;
alter table compressed_values alter column items set storage extended;
alter table compressed_values alter column items set compression pglz;
select ok(not exists(select 1 from plain_values p join compressed_values c using(id) where private.checklist_authoring_items_are_valid(p.items) is distinct from private.checklist_authoring_items_are_valid(c.items)),'equal JSON yields equal validation across uncompressed/external and compressed storage');
select ok(exists(select 1 from compressed_values where pg_column_compression(validation)='pglz' and pg_column_size(validation)<8192 and pg_column_size(validation||'{}'::jsonb)>8192 and not private.checklist_authoring_items_are_valid(items)),'compressed oversized validation is refused using the extracted logical value');
select is(private.checklist_authoring_items_are_valid(items),id<=8172,'binary validation boundary: '||id) from compressed_values where id in(8171,8172,8173)order by id;
create temporary table total_wire_cases(target int,items jsonb)on commit drop;
with prefix as(select jsonb_agg(jsonb_build_object('label','Check','instructions',repeat('x',5000)))items from generate_series(1,19)),base as(select items||jsonb_build_array(jsonb_build_object('label','Check','instructions',''))items from prefix)
select ok(octet_length(items::text)=target and private.checklist_authoring_items_are_valid(items)=(target<=100000),'aggregate wire boundary: '||target)from total_wire_cases order by target;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select lives_ok($$select public.create_checklist_template_version('b1000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','READINESS ONLY — authoring boundary','safety','[{"label":"Check","instructions":null,"response_type":"temperature","required":true,"validation":{}}]')$$,'Owner can create a valid inactive draft through actor-derived command');
select is((public.create_checklist_template_version('b1000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','READINESS ONLY — authoring boundary','safety','[{"label":"Check","instructions":null,"response_type":"temperature","required":true,"validation":{}}]')).id,'b1000000-0000-4000-8000-000000000001'::uuid,'exact draft retry returns same version');
select is((select count(*) from public.checklist_template_items where template_id='b1000000-0000-4000-8000-000000000001'),1::bigint,'exact draft retry creates only one item');
select throws_ok($$select public.create_checklist_template_version('b1000000-0000-4000-8000-000000000002','30000000-0000-4000-8000-000000000001','READINESS ONLY — rejected draft','safety','[{}]')$$,'22023','Invalid checklist template draft','malformed command refused before insert: missing label');
select throws_ok($$select public.create_checklist_template_version('b1000000-0000-4000-8000-000000000003','30000000-0000-4000-8000-000000000001','READINESS ONLY — rejected draft','safety','[{"label": "Check", "instructions": 42}]')$$,'22023','Invalid checklist template draft','malformed command refused before insert: number instructions');
select throws_ok($$select public.create_checklist_template_version('b1000000-0000-4000-8000-000000000004','30000000-0000-4000-8000-000000000001','READINESS ONLY — rejected draft','safety','[{"label": "Check", "instructions": {}}]')$$,'22023','Invalid checklist template draft','malformed command refused before insert: object instructions');
select throws_ok($$select public.create_checklist_template_version('b1000000-0000-4000-8000-000000000005','30000000-0000-4000-8000-000000000001','READINESS ONLY — rejected draft','safety','["value"]')$$,'22023','Invalid checklist template draft','malformed command refused before insert: non-object item');
reset role;
select is((select count(*) from public.checklist_templates where id between 'b1000000-0000-4000-8000-000000000002'::uuid and 'b1000000-0000-4000-8000-000000000005'::uuid),0::bigint,'invalid drafts create no template');
select is((select count(*) from private.operation_requests where request_id between 'b1000000-0000-4000-8000-000000000002'::uuid and 'b1000000-0000-4000-8000-000000000005'::uuid),0::bigint,'invalid drafts consume no operation receipt');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000005","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select public.create_checklist_template_version('b1000000-0000-4000-8000-000000000006','30000000-0000-4000-8000-000000000001','READINESS ONLY — denied draft','safety','[{"label":"Check"}]')$$,'42501',null,'Employee cannot author templates');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select public.create_checklist_template_version('b1000000-0000-4000-8000-000000000007','30000000-0000-4000-8000-000000000002','READINESS ONLY — denied draft','safety','[{"label":"Check"}]')$$,'42501',null,'Manager cannot author another location');
select throws_ok($$select public.create_checklist_template_version('b1000000-0000-4000-8000-000000000008','30000000-0000-4000-8000-000000000099','READINESS ONLY — denied draft','safety','[{"label":"Check"}]')$$,'42501',null,'Unknown location is refused without creating a draft');
reset role;
select * from finish();rollback;
